'use strict';

/**
 * Private file storage (backend-architecture.md section 17 with the FR2 decision 14 exception).
 * The only code that builds S3 keys and signs URLs. Reads process.env.FILES_BUCKET.
 * Import as require('common/s3'). Not exported from common/index.js, so services that do not use
 * files never load the S3 SDK.
 *
 * Files are private: there is no public files domain and therefore no fileUrl(). Downloads use
 * short-lived pre-signed GET URLs issued after the caller's scope check.
 *
 * The S3 SDK (@aws-sdk/client-s3, @aws-sdk/s3-request-presigner) is bundled in the Lambda package of
 * the service that uses this module (its package.json "dependencies"), not taken from the runtime.
 * A layer file cannot see /var/task/node_modules through normal resolution, so it is resolved from
 * the function package root first.
 */

const crypto = require('crypto');

const RANDOM_ALPHABET = 'abcdefghijklmnopqrstuvwxyz0123456789';
const MAX_BASE_LENGTH = 100;
const STORED_CACHE_CONTROL = 'private, no-store';
const UPLOAD_EXPIRES_IN = 900; // 15 minutes
const DOWNLOAD_EXPIRES_IN = 300; // 5 minutes

function loadSdk(name) {
    const paths = [process.env.LAMBDA_TASK_ROOT, process.cwd(), __dirname].filter(Boolean);
    return require(require.resolve(name, { paths }));
}

let sdk = null;
function getSdk() {
    if (!sdk) {
        const s3 = loadSdk('@aws-sdk/client-s3');
        const presigner = loadSdk('@aws-sdk/s3-request-presigner');
        sdk = {
            s3,
            getSignedUrl: presigner.getSignedUrl,
            // Created once per Lambda container. Checksums only when required: otherwise newer SDKs
            // add a checksum of an empty body to pre-signed PUT URLs and every browser upload fails.
            client: new s3.S3Client({
                requestChecksumCalculation: 'WHEN_REQUIRED',
                responseChecksumValidation: 'WHEN_REQUIRED',
            }),
        };
    }
    return sdk;
}

function bucket() {
    const name = process.env.FILES_BUCKET;
    if (!name) throw new Error('FILES_BUCKET is not set');
    return name;
}

function randomPrefix() {
    let out = '';
    for (let i = 0; i < 8; i += 1) out += RANDOM_ALPHABET[crypto.randomInt(RANDOM_ALPHABET.length)];
    return out;
}

/**
 * `<prefix>/<random8>-<name>`. The name keeps its extension exactly; other characters outside
 * A-Za-z0-9._- become '-', and the base name is cut to 100 characters.
 */
function buildFileKey(prefix, fileName) {
    const raw = String(fileName || '').split(/[\\/]/).pop();
    const dot = raw.lastIndexOf('.');
    const hasExt = dot > 0 && dot < raw.length - 1;
    const sanitize = (s) => s.replace(/[^A-Za-z0-9._-]/g, '-');
    let base = sanitize(hasExt ? raw.slice(0, dot) : raw).slice(0, MAX_BASE_LENGTH);
    const ext = hasExt ? sanitize(raw.slice(dot)) : '';
    if (base === '') base = 'file';
    return `${String(prefix).replace(/\/+$/, '')}/${randomPrefix()}-${base}${ext}`;
}

/**
 * Pre-signed PUT for a new object. Signs Content-Type, Content-Length (= size), Cache-Control and
 * If-None-Match: * so S3 rejects a different type, a different size, or a write to an existing key
 * (412). Returns { uploadUrl, uploadHeaders, expiresAt }; the client sends uploadHeaders unchanged
 * (the browser sets Content-Length itself from the body).
 */
async function createUploadUrl({ key, contentType, size, expiresIn = UPLOAD_EXPIRES_IN }) {
    const { s3, client, getSignedUrl } = getSdk();
    const command = new s3.PutObjectCommand({
        Bucket: bucket(),
        Key: key,
        ContentType: contentType,
        ContentLength: size,
        CacheControl: STORED_CACHE_CONTROL,
        IfNoneMatch: '*',
    });
    const uploadUrl = await getSignedUrl(client, command, {
        expiresIn,
        signableHeaders: new Set(['content-type', 'content-length', 'cache-control', 'if-none-match']),
    });
    return {
        uploadUrl,
        uploadHeaders: {
            'Content-Type': contentType,
            'Cache-Control': STORED_CACHE_CONTROL,
            'If-None-Match': '*',
        },
        expiresAt: new Date(Date.now() + expiresIn * 1000).toISOString(),
    };
}

function asciiFallback(name) {
    const ascii = String(name).replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_');
    return ascii || 'file';
}

/**
 * Pre-signed GET (default 5 minutes). PDF and images open inline, everything else downloads; the
 * original file name is kept (ASCII fallback plus RFC 5987 filename*). Returns { url, expiresAt }.
 */
async function createDownloadUrl({ key, fileName, contentType, expiresIn = DOWNLOAD_EXPIRES_IN }) {
    const { s3, client, getSignedUrl } = getSdk();
    const inline = contentType === 'application/pdf' || String(contentType).startsWith('image/');
    const disposition =
        `${inline ? 'inline' : 'attachment'}; filename="${asciiFallback(fileName)}"; ` +
        `filename*=UTF-8''${encodeURIComponent(fileName).replace(/['()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`)}`;
    const command = new s3.GetObjectCommand({
        Bucket: bucket(),
        Key: key,
        ResponseContentType: contentType,
        ResponseCacheControl: STORED_CACHE_CONTROL,
        ResponseContentDisposition: disposition,
    });
    const url = await getSignedUrl(client, command, { expiresIn });
    return { url, expiresAt: new Date(Date.now() + expiresIn * 1000).toISOString() };
}

/**
 * { size, contentType } of a stored object, or null when it is missing. Without s3:ListBucket S3
 * answers a missing key with 403, so NotFound, 404 and 403 all mean "missing".
 */
async function headFile(key) {
    const { s3, client } = getSdk();
    try {
        const res = await client.send(new s3.HeadObjectCommand({ Bucket: bucket(), Key: key }));
        return { size: res.ContentLength, contentType: res.ContentType };
    } catch (err) {
        const status = err && err.$metadata && err.$metadata.httpStatusCode;
        if ((err && (err.name === 'NotFound' || err.name === 'NoSuchKey')) || status === 404 || status === 403) return null;
        throw err;
    }
}

/** Deletes one object. Only for features whose plan deletes files. */
async function deleteFile(key) {
    const { s3, client } = getSdk();
    await client.send(new s3.DeleteObjectCommand({ Bucket: bucket(), Key: key }));
}

module.exports = { buildFileKey, createUploadUrl, createDownloadUrl, headFile, deleteFile };
